"use client";

import { useCallback, useRef, useState } from "react";
import { Icon } from "@/components/nx/Icon";
import { beginUpload, endUpload } from "@/lib/upload-in-progress";
import type { FileApi } from "@/lib/files-types";

/**
 * Uploads with a progress bar that reflects bytes actually sent.
 *
 * The file manager used `fetch` with a FormData body, which gives no upload
 * progress at all — the whole UI was one boolean and a button that read
 * "Uploading…". On a 200 MB world that is several minutes of a customer not
 * knowing whether anything is happening. `fetch` cannot report request-body
 * progress in any browser today, so this uses XMLHttpRequest, whose
 * `upload.onprogress` gives loaded/total for free.
 *
 * Files upload one at a time on purpose: the destination is a single SSH/SFTP
 * connection per request, and three concurrent 200 MB writes to one VM is a
 * worse experience than three sequential ones, not a better one.
 *
 * The destination URL comes from the FileApi the browser is driving
 * (`api.uploadUrl(dir)`), because a VPS upload and a shared-hosting upload land
 * on different routes — everything else about the queue is backend-agnostic.
 */

export type UploadItem = {
  id: string;
  name: string;
  size: number;
  sent: number;
  /** bytes/second over the last sample window; null until there are two samples */
  rate: number | null;
  status: "queued" | "uploading" | "done" | "failed" | "cancelled";
  error?: string;
};

function fmtSize(b: number): string {
  if (b < 1024) return `${b} B`;
  if (b < 1024 ** 2) return `${(b / 1024).toFixed(1)} KB`;
  if (b < 1024 ** 3) return `${(b / 1024 ** 2).toFixed(1)} MB`;
  return `${(b / 1024 ** 3).toFixed(2)} GB`;
}

function fmtEta(item: UploadItem): string {
  if (item.status !== "uploading" || !item.rate || item.rate <= 0) return "";
  const left = Math.max(0, item.size - item.sent) / item.rate;
  if (left < 60) return `${Math.ceil(left)}s left`;
  return `${Math.ceil(left / 60)}m left`;
}

export function useUploadQueue(api: FileApi, path: string, onDone: () => void) {
  const [items, setItems] = useState<UploadItem[]>([]);
  const xhrRef = useRef<XMLHttpRequest | null>(null);
  const runningRef = useRef(false);

  const patch = (id: string, p: Partial<UploadItem>) =>
    setItems((xs) => xs.map((x) => (x.id === id ? { ...x, ...p } : x)));

  const sendOne = (item: UploadItem, file: File) =>
    new Promise<void>((resolve) => {
      const xhr = new XMLHttpRequest();
      xhrRef.current = xhr;
      let lastT = Date.now();
      let lastB = 0;

      xhr.upload.onprogress = (e) => {
        if (!e.lengthComputable) return;
        const now = Date.now();
        const dt = (now - lastT) / 1000;
        // Sample the rate rather than computing it from the start, so a stall
        // shows as a stall instead of being averaged away.
        const rate = dt > 0.25 ? (e.loaded - lastB) / dt : null;
        if (rate !== null) { lastT = now; lastB = e.loaded; }
        patch(item.id, { sent: e.loaded, status: "uploading", ...(rate !== null ? { rate } : {}) });
      };
      xhr.onload = () => {
        if (xhr.status >= 200 && xhr.status < 300) {
          patch(item.id, { sent: item.size, status: "done", rate: null });
        } else {
          let msg = `Upload failed (${xhr.status}).`;
          try { msg = JSON.parse(xhr.responseText)?.error || msg; } catch { /* keep the status */ }
          patch(item.id, { status: "failed", error: msg });
        }
        resolve();
      };
      xhr.onerror = () => { patch(item.id, { status: "failed", error: "Connection lost during upload." }); resolve(); };
      xhr.onabort = () => { patch(item.id, { status: "cancelled" }); resolve(); };

      const fd = new FormData();
      fd.set("file", file);
      xhr.open("POST", api.uploadUrl(path));
      xhr.send(fd);
    });

  const enqueue = useCallback(
    async (list: FileList | File[]) => {
      const files = Array.from(list);
      if (!files.length || runningRef.current) return;

      const batch: UploadItem[] = files.map((f, i) => ({
        id: `${Date.now()}-${i}-${f.name}`,
        name: f.name,
        size: f.size,
        sent: 0,
        rate: null,
        status: "queued",
      }));
      setItems((xs) => [...xs.filter((x) => x.status !== "done"), ...batch]);

      runningRef.current = true;
      // Suppress AutoRefresh's periodic router.refresh() for the duration —
      // without it a long upload can have the page pulled out from under it.
      beginUpload();
      try {
        for (let i = 0; i < files.length; i++) await sendOne(batch[i], files[i]);
      } finally {
        endUpload();
        runningRef.current = false;
        xhrRef.current = null;
        onDone();
      }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps -- sendOne closes over stable refs
    [api.key, path, onDone],
  );

  const cancel = () => xhrRef.current?.abort();
  const dismiss = (id: string) => setItems((xs) => xs.filter((x) => x.id !== id));
  const clearDone = () => setItems((xs) => xs.filter((x) => x.status === "uploading" || x.status === "queued"));

  return { items, enqueue, cancel, dismiss, clearDone, busy: runningRef.current };
}

export function UploadQueue({
  items, onCancel, onDismiss, onClearDone,
}: {
  items: UploadItem[]; onCancel: () => void; onDismiss: (id: string) => void; onClearDone: () => void;
}) {
  if (items.length === 0) return null;
  const active = items.some((i) => i.status === "uploading" || i.status === "queued");

  return (
    <div className="rounded-[14px] border border-rim-hi bg-[rgba(6,14,36,.82)] p-3.5">
      <div className="mb-2.5 flex items-center gap-3">
        <Icon name="upload" size={15} tone="inherit" className="text-[#7fb0ff]" />
        <h4 className="text-[13px] font-bold text-white">
          {active ? "Uploading" : "Uploads"}
          <span className="ml-2 font-medium text-tx-faint">
            {items.filter((i) => i.status === "done").length}/{items.length} complete
          </span>
        </h4>
        {active ? (
          <button type="button" onClick={onCancel}
                  className="ml-auto rounded-[9px] border border-red-500/40 px-3 py-1.5 text-[12px] font-semibold text-red-300 transition hover:bg-red-500/10">
            Cancel current
          </button>
        ) : (
          <button type="button" onClick={onClearDone}
                  className="ml-auto rounded-[9px] border border-rim-hi px-3 py-1.5 text-[12px] font-semibold text-tx-dim transition hover:text-white">
            Clear
          </button>
        )}
      </div>

      <ul className="flex flex-col gap-2">
        {items.map((i) => {
          const pct = i.size > 0 ? Math.min(100, (i.sent / i.size) * 100) : i.status === "done" ? 100 : 0;
          const failed = i.status === "failed";
          const done = i.status === "done";
          return (
            <li key={i.id} className="flex flex-col gap-1.5 rounded-[11px] border border-rim-soft bg-well px-3 py-2.5">
              <div className="flex items-center gap-2.5">
                <Icon
                  name={done ? "checkcircle" : failed ? "xcircle" : "file"}
                  size={14}
                  tone="inherit"
                  className={"flex-none " + (done ? "text-emerald-400" : failed ? "text-red-400" : "text-tx-faint")}
                />
                <span className="min-w-0 flex-1 truncate text-[12.5px] font-semibold text-white">{i.name}</span>
                <span className="flex-none text-[11.5px] text-tx-faint">
                  {done ? fmtSize(i.size)
                    : failed || i.status === "cancelled" ? ""
                    : `${fmtSize(i.sent)} / ${fmtSize(i.size)}`}
                </span>
                <span className={"w-[46px] flex-none text-right text-[12px] font-bold tabular-nums " +
                  (done ? "text-emerald-400" : failed ? "text-red-400" : "text-white")}>
                  {done ? "100%" : failed ? "—" : i.status === "cancelled" ? "—" : `${Math.round(pct)}%`}
                </span>
                {(done || failed || i.status === "cancelled") && (
                  <button type="button" onClick={() => onDismiss(i.id)} aria-label={`Dismiss ${i.name}`}
                          className="flex-none text-tx-faint transition hover:text-white">
                    <Icon name="xcircle" size={13} tone="inherit" />
                  </button>
                )}
              </div>

              <span className="h-[5px] w-full overflow-hidden rounded-full bg-white/10">
                <span
                  className={"block h-full rounded-full transition-[width] duration-200 " +
                    (done ? "bg-emerald-400" : failed ? "bg-red-400" : "bg-[linear-gradient(90deg,#2f6fe0,#7b3fef)]")}
                  style={{ width: `${failed || i.status === "cancelled" ? 100 : pct}%` }}
                />
              </span>

              {(i.status === "uploading" || failed) && (
                <span className={"text-[11px] " + (failed ? "text-red-300" : "text-tx-faint")}>
                  {failed
                    ? i.error
                    : [i.rate ? `${fmtSize(i.rate)}/s` : null, fmtEta(i)].filter(Boolean).join(" · ")}
                </span>
              )}
            </li>
          );
        })}
      </ul>
    </div>
  );
}
  if (name.length > MAX_NAME_LEN) throw new Error("Name is too long.");
  if (name.includes("/") || name.includes("\0")) throw new Error("Name contains invalid characters.");
  if (name === "." || name === "..") throw new Error("That name is not allowed.");
  return name;
}

/** Join a validated absolute dir with a validated name, re-normalizing. */
export function joinPath(dir: string, name: string): string {
  return normalizePath(`${dir}/${name}`);
}

/**
 * Fixed directory every browser→server upload lands in. Uploads are ALWAYS
 * written here under a sanitized basename — never at a client-chosen path — so
 * a hostile filename can only ever create a file inside this one dir. Lives in
 * this plain module (not the "use server" action file) so it can be imported
 * and unit-tested without pulling in the server-action graph.
 */
export const UPLOAD_DIR = "/root/nxeon-uploads";

/**
 * Reduce an arbitrary, client-supplied filename to a SAFE basename that can only
 * land inside {@link UPLOAD_DIR}. Strips every directory component (POSIX `/`
 * and Windows `\`) so `../../etc/passwd` or `C:\evil\x` collapse to their final
 * segment, then runs the survivor through the same `validateName` the file
 * manager uses (rejects `/`, NUL, `.`, `..`, over-long names). Pure so the guard
 * can be unit-tested in isolation from any SFTP connection.
 */
export function sanitizeUploadName(raw: string): string {
  if (typeof raw !== "string") throw new Error("A name is required.");
  const base = raw.split(/[/\\]/).pop() ?? "";
  const trimmed = base.trim();
  if (!trimmed) throw new Error("A name is required.");
  return validateName(trimmed);
}

/**
 * Resolve the {host, port} for a server, mirroring the server detail page:
 * dedicated IP -> :22, otherwise the server's OWN node's public IP : sshPort
 * (falling back to the platform's env-configured primary only when the
 * server genuinely has no node relation — e.g. not yet selected by an older
 * caller, or a row that predates multi-node). Getting this wrong for a
 * server on a non-primary node means dialing the WRONG physical host
 * entirely, not just a wrong port — verified live 2026-09-05 as the root
 * cause of an entire class of "control panel dead for node-2" bugs.
 */
export function connectionTarget(server: SftpServer): { host: string; port: number } | null {
  const dedicated = !!server.dedicatedIp;
  const host = dedicated ? server.dedicatedIp!.address : (server.node?.publicIp ?? process.env.PUBLIC_IP ?? "");
  const port = dedicated ? (server.guestSshPort ?? 22) : server.sshPort;
  if (!host || !port) return null;
  return { host, port };
}

/**
 * Open an SFTP connection, run `fn(client)`, and ALWAYS close it (finally).
 * In SANDBOX mode this is bypassed entirely — callers below short-circuit to
 * the in-memory filesystem before ever reaching here.
 */
export async function withSftp<T>(
  server: SftpServer,
  fn: (client: SftpClient) => Promise<T>
): Promise<T> {
  if (SANDBOX) {
    throw new Error("withSftp must not be called in sandbox mode");
  }
  const target = connectionTarget(server);
  if (!target) throw new Error("Server is not reachable yet — connection details are pending.");
  const privateKey = serverManagementKey(server);
  const password = serverRootPassword(server);
  if (!privateKey && !password) throw new Error("Server has no root password set.");

  // Try the per-server management key first (see Server.sshManagementKeyEnc's
  // schema doc comment) — falls back to the password if there's no key on file
  // yet, or if the key is present but the connection fails for any reason (a
  // customer could have deleted our line from their own authorized_keys; that
  // must degrade to today's behavior, not break the tool outright). A fresh
  // client per attempt — reusing one after a failed connect is not a state
  // ssh2-sftp-client guarantees to recover from cleanly.
  if (privateKey) {
    const keyClient = new SftpClient();
  }

  await withSftp(server, async (client) => {
    await client.put(Buffer.from(content, "utf8"), path);
  });
}

export async function mkdirPath(server: SftpServer, path: string): Promise<void> {
  if (SANDBOX) {
    const loc = simParent(server.id, path);
    if (!loc) throw new Error("Invalid path.");
    if (loc.parent.children[loc.name]) throw new Error("A file or folder with that name already exists.");
    loc.parent.children[loc.name] = { type: "dir", mtime: Date.now(), mode: 0o755, children: {} };
    return;
  }

  await withSftp(server, async (client) => {
    await client.mkdir(path, false);
  });
}

export async function renamePath(
    return (await client.get(path)) as Buffer;
  });
}

/** Write a Buffer to a path (used by the upload endpoint). */
export async function writeFileBuffer(
  server: SftpServer,
  path: string,
  data: Buffer
): Promise<void> {
  if (SANDBOX) {
    const loc = simParent(server.id, path);
    if (!loc) throw new Error("Invalid path.");
    const existing = loc.parent.children[loc.name];
    if (existing && existing.type === "dir") throw new Error("Path is a directory.");
    loc.parent.children[loc.name] = {
      type: "file",
      mtime: Date.now(),
      mode: existing?.type === "file" ? existing.mode : 0o644,
      content: data.toString("utf8"),
    };
    return;
  }

  await withSftp(server, async (client) => {
    await client.put(data, path);
  });
}
