/** A unit of work for the upload queue: one file, or one (empty) directory. */
export type FlatEntry =
  | { kind: "file"; relPath: string; file: File }
  | { kind: "dir"; relPath: string };

export type FlattenResult = { entries: FlatEntry[]; error?: string };

/** Flatten the files from an `<input webkitdirectory>` / multi-select using webkitRelativePath. */
export function flattenFileList(files: ArrayLike<File>): FlattenResult {
  const entries: FlatEntry[] = [];
  for (let i = 0; i < files.length; i++) {
    const f = files[i];
    const rel = (f as File & { webkitRelativePath?: string }).webkitRelativePath || f.name;
    entries.push({ kind: "file", relPath: rel, file: f });
  }
  return { entries, error: checkEntries(entries) };
}

/** Whole-batch checks (count + per-path rules). Returns an error message or undefined. */
export function checkEntries(entries: FlatEntry[]): string | undefined {
  if (entries.length > MAX_FOLDER_ENTRIES)
    return `That is ${entries.length.toLocaleString()} items — folder uploads are limited to ${MAX_FOLDER_ENTRIES.toLocaleString()} files per upload. Zip it first or upload in parts.`;
  for (const e of entries) {
    try { parseRelPath(e.relPath, e.kind); }
    catch (err) { return `"${e.relPath}": ${err instanceof Error ? err.message : "invalid path"}`; }
  }
  return undefined;
}

// ---- drag-and-drop traversal (webkitGetAsEntry) ---------------------------

/** The slice of FileSystemEntry we use — structural so tests can fake it. */
export type FsEntry = {
  isFile: boolean;
  isDirectory: boolean;
  name: string;
  file?: (ok: (f: File) => void, err: (e: unknown) => void) => void;
  createReader?: () => { readEntries: (ok: (xs: FsEntry[]) => void, err: (e: unknown) => void) => void };
};

/** readEntries returns results in batches (~100 in Chrome); it MUST be called until it returns []. */
async function readAll(dir: FsEntry): Promise<FsEntry[]> {
  const reader = dir.createReader!();
  const out: FsEntry[] = [];
  for (;;) {
    const batch = await new Promise<FsEntry[]>((res, rej) => reader.readEntries(res, rej));
    if (batch.length === 0) return out;
    out.push(...batch);
    if (out.length > MAX_FOLDER_ENTRIES * 2) return out; // runaway guard; caller reports the cap
  }
}

/**
 * Recursively flatten dropped entries into files + empty directories.
 * Stops early (with an error) once the entry cap or depth cap is exceeded.
 */
export async function walkEntries(roots: FsEntry[]): Promise<FlattenResult> {
  const entries: FlatEntry[] = [];
  let error: string | undefined;

  async function visit(e: FsEntry, prefix: string, depth: number): Promise<void> {
    if (error) return;
    const rel = prefix + e.name;
    if (entries.length > MAX_FOLDER_ENTRIES) {
      error = checkEntries(entries);
      return;
    }
    if (e.isFile) {
      try {
        const file = await new Promise<File>((res, rej) => e.file!(res, rej));
        entries.push({ kind: "file", relPath: rel, file });
      } catch {
        error = `Couldn't read "${rel}" — the browser refused access to it.`;
      }
      return;
    }
    if (e.isDirectory) {
      if (depth >= MAX_FOLDER_DEPTH) {
        error = `Folders nested deeper than ${MAX_FOLDER_DEPTH} levels can't be uploaded.`;
        return;
      }
      let kids: FsEntry[];
      try { kids = await readAll(e); }
      catch { error = `Couldn't read the folder "${rel}".`; return; }
      // Empty directories have nothing to carry them, so they are sent explicitly.
      if (kids.length === 0) { entries.push({ kind: "dir", relPath: rel }); return; }
      for (const k of kids) await visit(k, rel + "/", depth + 1);
    }
  }

  for (const r of roots) await visit(r, "", 0);
  return { entries, error: error ?? checkEntries(entries) };
}

/**
 * Gather a drop. MUST be called synchronously inside the drop handler: the
 * DataTransferItemList is emptied once the event returns, so every
 * webkitGetAsEntry() call happens before the first await.
 */
export function collectDrop(dt: DataTransfer): Promise<FlattenResult & { folders: boolean }> {
  const items = Array.from(dt.items ?? []);
  const supported = items.length > 0 && typeof (items[0] as DataTransferItem & { webkitGetAsEntry?: unknown }).webkitGetAsEntry === "function";
  if (!supported) {
    const r = flattenFileList(Array.from(dt.files ?? []));
    return Promise.resolve({ ...r, folders: false });
  }
  const roots: FsEntry[] = [];
  for (const it of items) {
    if (it.kind !== "file") continue;
    const ent = (it as DataTransferItem & { webkitGetAsEntry(): FsEntry | null }).webkitGetAsEntry();
    if (ent) roots.push(ent);
  }
  return walkEntries(roots).then((r) => ({ ...r, folders: roots.some((x) => x.isDirectory) }));
}
