/**
 * `mkdir -p`: create `path` and any missing parents; a no-op when it already
 * exists as a directory. Used by folder uploads. Callers pass an already
 * validated absolute path.
 */
export async function mkdirpPath(server: SftpServer, path: string): Promise<void> {
  if (SANDBOX) {
    let cur = "";
    for (const seg of splitPath(path)) {
      cur += "/" + seg;
      const node = simResolve(server.id, cur);
      if (node) {
        if (node.type !== "dir") throw new Error("A file with that name already exists.");
        continue;
      }
      const loc = simParent(server.id, cur);
      if (!loc) throw new Error("Invalid path.");
      loc.parent.children[loc.name] = { type: "dir", mtime: Date.now(), mode: 0o755, children: {} };
    }
    return;
  }

  await withSftp(server, async (client) => {
    // ssh2-sftp-client's recursive mkdir stats each level and only creates
    // what is missing; it rejects if a level exists as a non-directory.
    await client.mkdir(path, true);
  });
}
