hook='''export function useUploadQueue(
  api: FileApi,
  path: string,
  onDone: () => void,
  onNotice?: (msg: string) => void,
) {
  const [items, setItems] = useState<UploadItem[]>([]);
  // File objects and per-item request details live outside React state.
  const jobsRef = useRef(new Map<string, { entry: FlatEntry; dest: string }>());
  const xhrsRef = useRef(new Map<string, XMLHttpRequest>());
  const pendingRef = useRef<string[]>([]);
  const activeRef = useRef(0);
  const cancelledRef = useRef(false);
  const seqRef = useRef(0);
  const [busy, setBusy] = useState(false);
  const onDoneRef = useRef(onDone);
  onDoneRef.current = onDone;

  const patch = (id: string, p: Partial<UploadItem>) =>
    setItems((xs) => xs.map((x) => (x.id === id ? { ...x, ...p } : x)));

  const sendOne = (id: string, size: number) =>
    new Promise<void>((resolve) => {
      const job = jobsRef.current.get(id);
      if (!job) return resolve();
      const xhr = new XMLHttpRequest();
      xhrsRef.current.set(id, xhr);
      let lastT = Date.now();
      let lastB = 0;
      patch(id, { status: "uploading", sent: 0, error: undefined });

      xhr.upload.onprogress = (e) => {
        if (!e.lengthComputable) return;
        const now = Date.now();
        const dt = (now - lastT) / 1000;
        // Sample the rate rather than computing it from the start, so a stall
        // shows as a stall instead of being averaged away.
        const rate = dt > 0.25 ? (e.loaded - lastB) / dt : null;
        if (rate !== null) { lastT = now; lastB = e.loaded; }
        patch(id, { sent: Math.min(e.loaded, size), status: "uploading", ...(rate !== null ? { rate } : {}) });
      };
      xhr.onload = () => {
        if (xhr.status >= 200 && xhr.status < 300) {
          patch(id, { sent: size, status: "done", rate: null });
        } else {
          let msg = `Upload failed (${xhr.status}).`;
          if (xhr.status === 429) msg = "Slowed down by the upload limit — use Retry in a moment.";
          try { msg = JSON.parse(xhr.responseText)?.error || msg; } catch { /* keep the status */ }
          patch(id, { status: "failed", error: msg });
        }
        resolve();
      };
      xhr.onerror = () => {
        patch(id, {
          status: "failed",
          error: "Connection lost during upload. If this was a folder, use the Upload folder button instead of dragging it.",
        });
        resolve();
      };
      xhr.onabort = () => { patch(id, { status: "cancelled" }); resolve(); };

      const fd = new FormData();
      if (job.entry.kind === "file") {
        fd.set("file", job.entry.file);
        if (job.entry.relPath.includes("/")) fd.set("relPath", job.entry.relPath);
      } else {
        fd.set("mkdir", "1");
        fd.set("relPath", job.entry.relPath);
      }
      xhr.open("POST", api.uploadUrl(job.dest));
      xhr.send(fd);
    }).finally(() => { xhrsRef.current.delete(id); });

  const finishIfIdle = () => {
    if (activeRef.current === 0 && pendingRef.current.length === 0) {
      endUpload();
      cancelledRef.current = false;
      setBusy(false);
      onDoneRef.current();
    }
  };

  const pump = () => {
    while (activeRef.current < CONCURRENCY && pendingRef.current.length > 0) {
      const id = pendingRef.current.shift()!;
      activeRef.current++;
      const size = jobsRef.current.get(id)?.entry.kind === "file"
        ? (jobsRef.current.get(id)!.entry as { file: File }).file.size : 0;
      void sendOne(id, size).finally(() => { activeRef.current--; pump(); finishIfIdle(); });
    }
  };

  const start = (ids: string[]) => {
    if (ids.length === 0) return;
    const wasIdle = activeRef.current === 0 && pendingRef.current.length === 0;
    if (wasIdle) {
      // Suppress AutoRefresh's periodic router.refresh() for the duration —
      // without it a long upload can have the page pulled out from under it.
      beginUpload();
      cancelledRef.current = false;
      setBusy(true);
    }
    pendingRef.current.push(...ids);
    pump();
  };

  /** Queue a batch of flattened entries (files, folder files, empty folders). */
  const enqueue = useCallback(
    (entries: FlatEntry[], error?: string) => {
      if (error) { onNotice?.(error); return; }
      if (!entries.length) return;
      const hasFolders = entries.some((e) => e.kind === "dir" || e.relPath.includes("/"));
      if (hasFolders && !api.supportsFolders) {
        onNotice?.("Folder uploads aren't available for this file manager yet — upload files individually or zip the folder.");
        return;
      }
      const batchId = `${Date.now()}-${++seqRef.current}`;
      const dest = path;
      const batch: UploadItem[] = entries.map((e, i) => {
        const id = `${batchId}-${i}`;
        jobsRef.current.set(id, { entry: e, dest });
        return {
          id,
          name: e.relPath,
          size: e.kind === "file" ? e.file.size : 0,
          sent: 0,
          rate: null,
          status: "queued" as const,
          group: e.relPath.includes("/") || e.kind === "dir" ? e.relPath.split("/")[0] + `#${batchId}` : undefined,
          isDir: e.kind === "dir",
        };
      });
      setItems((xs) => [...xs.filter((x) => x.status !== "done"), ...batch]);
      start(batch.map((b) => b.id));
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps -- start/pump close over stable refs
    [api.key, api.supportsFolders, path, onNotice],
  );

  const retry = (ids: string[]) => {
    const ok = ids.filter((id) => jobsRef.current.has(id));
    for (const id of ok) patch(id, { status: "queued", error: undefined, sent: 0 });
    start(ok);
  };

  const cancel = () => {
    cancelledRef.current = true;
    const queued = pendingRef.current.splice(0);
    setItems((xs) => xs.map((x) => (queued.includes(x.id) ? { ...x, status: "cancelled" as const } : x)));
    for (const x of xhrsRef.current.values()) x.abort();
    finishIfIdle();
  };
  const dismiss = (id: string) => { jobsRef.current.delete(id); setItems((xs) => xs.filter((x) => x.id !== id)); };
  const clearDone = () => setItems((xs) => xs.filter((x) => x.status === "uploading" || x.status === "queued"));

  return { items, enqueue, retry, cancel, dismiss, clearDone, busy };
}

