}

/** One folder upload: a single overall progress bar, files tucked under a toggle. */
function GroupRow({ name, items, onDismiss, onRetry }: {
  name: string; items: UploadItem[]; onDismiss: (id: string) => void; onRetry: (ids: string[]) => void;
}) {
  const [open, setOpen] = useState(false);
  const total = items.reduce((a, x) => a + x.size, 0);
  const sent = items.reduce((a, x) => a + (x.status === "done" ? x.size : x.sent), 0);
  const doneN = items.filter((x) => x.status === "done").length;
  const bad = items.filter((x) => x.status === "failed" || x.status === "cancelled");
  const failed = items.filter((x) => x.status === "failed").length;
  const pct = total > 0 ? Math.min(100, (sent / total) * 100) : (doneN / items.length) * 100;
  const finished = doneN === items.length;
  // Failures are the thing to look at: surface them without a click.
  const expanded = open || failed > 0;
  const shownItems = open ? items : items.filter((x) => x.status === "failed");
  return (
    <li className="flex flex-col gap-1.5 rounded-[11px] border border-rim-soft bg-well px-3 py-2.5">
      <div className="flex items-center gap-2.5">
        <Icon name={finished ? "checkcircle" : failed ? "xcircle" : "folder"} size={14} tone="inherit"
              className={"flex-none " + (finished ? "text-emerald-400" : failed ? "text-red-400" : "text-[#7fb0ff]")} />
        <button type="button" onClick={() => setOpen((o) => !o)} aria-expanded={expanded}
                className="min-w-0 flex-1 truncate text-left text-[12.5px] font-semibold text-white">
          {name}/ <span className="font-medium text-tx-faint">{doneN}/{items.length} items</span>
        </button>
        <span className="flex-none text-[11.5px] text-tx-faint">{fmtSize(sent)} / {fmtSize(total)}</span>
        <span className="w-[46px] flex-none text-right text-[12px] font-bold tabular-nums text-white">{Math.round(pct)}%</span>
        {bad.length > 0 && <RetryButton onClick={() => onRetry(bad.map((x) => x.id))} label={`Retry ${bad.length} failed`} />}
      </div>
      <span className="h-[5px] w-full overflow-hidden rounded-full bg-white/10">
        <span className={"block h-full rounded-full transition-[width] duration-200 " +
          (finished ? "bg-emerald-400" : failed ? "bg-red-400" : "bg-[linear-gradient(90deg,#2f6fe0,#7b3fef)]")}
          style={{ width: `${pct}%` }} />
      </span>
      {expanded && shownItems.length > 0 && (
        <ul className="mt-1 flex max-h-[260px] flex-col gap-2 overflow-auto">
          {shownItems.map((i) => <ItemRow key={i.id} i={i} onDismiss={onDismiss} onRetry={onRetry} />)}
        </ul>
      )}
    </li>
  );
