import test from "node:test";
import assert from "node:assert/strict";
import {
  parseRelPath, flattenFileList, walkEntries, checkEntries,
  MAX_FOLDER_DEPTH, MAX_FOLDER_ENTRIES, type FsEntry,
} from "../lib/upload-paths";

const f = (name: string, rel?: string) => Object.assign(new File(["x"], name), rel ? { webkitRelativePath: rel } : {});

test("parseRelPath accepts normal nested paths", () => {
  assert.deepEqual(parseRelPath("Mod/lib/a.jar"), ["Mod", "lib", "a.jar"]);
  assert.deepEqual(parseRelPath("a.txt"), ["a.txt"]);
  assert.deepEqual(parseRelPath("Mod/empty", "dir"), ["Mod", "empty"]);
});

test("parseRelPath rejects hostile input", () => {
  for (const bad of ["../x", "a/../b", "/etc/passwd", "a\\b", "a/./b", "a//b", "a/", "", "a\0b", "a/\nb", ".", ".."]) {
    assert.throws(() => parseRelPath(bad), undefined, JSON.stringify(bad));
  }
  assert.throws(() => parseRelPath(42 as unknown), /required/);
  assert.throws(() => parseRelPath("a/" + "x".repeat(256)), /segment/);
  assert.throws(() => parseRelPath(("a/".repeat(600)) + "b"), /long/);
});

test("depth cap: 12 dirs ok, 13 rejected", () => {
  const ok = Array(MAX_FOLDER_DEPTH).fill("d").join("/") + "/f";
  const bad = Array(MAX_FOLDER_DEPTH + 1).fill("d").join("/") + "/f";
  assert.doesNotThrow(() => parseRelPath(ok));
  assert.throws(() => parseRelPath(bad), /deeper/);
  assert.throws(() => parseRelPath(Array(MAX_FOLDER_DEPTH + 1).fill("d").join("/"), "dir"), /deeper/);
});

test("flattenFileList uses webkitRelativePath and falls back to name", () => {
  const r = flattenFileList([f("a.jar", "Mod/lib/a.jar"), f("loose.txt")]);
  assert.equal(r.error, undefined);
  assert.deepEqual(r.entries.map((e) => e.relPath), ["Mod/lib/a.jar", "loose.txt"]);
});

test("entry-count cap", () => {
  const many = Array.from({ length: MAX_FOLDER_ENTRIES + 1 }, (_, i) => f(`${i}`, `M/${i}`));
  assert.match(flattenFileList(many).error ?? "", /limited to/);
  assert.equal(checkEntries([]), undefined);
});

// ---- fake FileSystemEntry tree; readEntries returns small batches ----
const fileE = (name: string): FsEntry => ({ isFile: true, isDirectory: false, name, file: (ok) => ok(f(name)) });
const dirE = (name: string, kids: FsEntry[], batch = 2): FsEntry => ({
  isFile: false, isDirectory: true, name,
  createReader: () => {
    let i = 0;
    return { readEntries: (ok) => { const b = kids.slice(i, i + batch); i += batch; ok(b); } };
  },
});

test("walkEntries loops readEntries until empty, keeps relative paths, emits empty dirs", async () => {
  const tree = dirE("ZenDragon", [
    fileE("a"), fileE("b"), fileE("c"), fileE("d"), fileE("e"), // 5 files, batch of 2 => 3 reads
    dirE("sub", [fileE("x")]),
    dirE("empty", []),
  ]);
  const r = await walkEntries([tree, fileE("loose")]);
  assert.equal(r.error, undefined);
  const paths = r.entries.map((e) => `${e.kind}:${e.relPath}`).sort();
  assert.deepEqual(paths, [
    "dir:ZenDragon/empty", "file:ZenDragon/a", "file:ZenDragon/b", "file:ZenDragon/c",
    "file:ZenDragon/d", "file:ZenDragon/e", "file:ZenDragon/sub/x", "file:loose",
  ].sort());
});

test("walkEntries reports too-deep trees and unreadable files", async () => {
  let t: FsEntry = fileE("leaf");
  for (let i = 0; i < MAX_FOLDER_DEPTH + 2; i++) t = dirE("d", [t]);
  assert.match((await walkEntries([t])).error ?? "", /deeper/);
  const bad: FsEntry = { isFile: true, isDirectory: false, name: "nope", file: (_ok, err) => err(new Error("denied")) };
  assert.match((await walkEntries([bad])).error ?? "", /refused/);
});
