  const tree = dirE("ZenDragon", [
    fileE("a"), fileE("b"), fileE("c"), fileE("d"), fileE("e"), // 5 files, batch of 2 => 3 reads
    dirE("sub", [fileE("x")]),
    dirE("empty", []),
  ]);
  const r = await walkEntries([tree, fileE("loose")]);
  assert.equal(r.error, undefined);
  const paths = r.entries.map((e) => `${e.kind}:${e.relPath}`).sort();
  assert.deepEqual(paths, [
    "dir:ZenDragon/empty", "file:ZenDragon/a", "file:ZenDragon/b", "file:ZenDragon/c",
    "file:ZenDragon/d", "file:ZenDragon/e", "file:ZenDragon/sub/x", "file:loose",
  ].sort());
});

test("walkEntries reports too-deep trees and unreadable files", async () => {
  let t: FsEntry = fileE("leaf");
  for (let i = 0; i < MAX_FOLDER_DEPTH + 2; i++) t = dirE("d", [t]);
  assert.match((await walkEntries([t])).error ?? "", /deeper/);
  const bad: FsEntry = { isFile: true, isDirectory: false, name: "nope", file: (_ok, err) => err(new Error("denied")) };
  assert.match((await walkEntries([bad])).error ?? "", /refused/);
});
